    this._material = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0xffffff,
      emissiveIntensity: 1.6,
      roughness: 0.35,
      metalness: 0.05,
      transparent: true,
      opacity: 1
    });
