async () => {
  const g = window.__spaceInvadersGame;
  const cells = [];
  g._formation.forEachAliveCell(c => cells.push(c));
  const target = cells.find(c => c.row === 4);
  g._player.mesh.position.x = target.worldX;

  window.dispatchEvent(new KeyboardEvent('keydown', { code: 'Space' }));
  await new Promise(r => setTimeout(r, 50));
  window.dispatchEvent(new KeyboardEvent('keyup', { code: 'Space' }));

  await new Promise(r => setTimeout(r, 400));

  return {
    targetX: target.worldX,
    targetRow: target.row,
    aliveAfter: g._formation.aliveCount,
    score: g._scoring.score,
    playerX: g._player.mesh.position.x
  };
}

