import * as THREE from 'three';
import { MAX_ACTIVE_PARTICLES } from '../utils/Constants.js';

const _matrix = new THREE.Matrix4();
const _position = new THREE.Vector3();
const _scaleVec = new THREE.Vector3();
const _zeroScale = new THREE.Vector3(0, 0, 0);
const _identityQuat = new THREE.Quaternion();
const _tmpColor = new THREE.Color();

/**
 * Centralized particle system for the whole collection. Backed by a single
 * InstancedMesh capped at MAX_ACTIVE_PARTICLES (500) — the mesh always draws
 * `capacity` instances in one draw call; inactive slots are zero-scaled so
 * they cost nothing visually. When capacity is exhausted, the oldest active
 * particle is evicted to make room for a new one (hard cap, never grows).
 */
export class ParticleManager {
  constructor(scene, { capacity = MAX_ACTIVE_PARTICLES, disposer = null } = {}) {
    this._capacity = capacity;

    this._geometry = new THREE.OctahedronGeometry(0.12, 0);
    this._material = new THREE.MeshStandardMaterial({
      color: 0xffffff,
      emissive: 0xffffff,
      emissiveIntensity: 1.6,
      roughness: 0.35,
      metalness: 0.05,
      transparent: true,
      opacity: 1
    });
    disposer?.trackGeometry(this._geometry);
    disposer?.trackMaterial(this._material);

    this._mesh = new THREE.InstancedMesh(this._geometry, this._material, capacity);
    this._mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    this._mesh.frustumCulled = false;
    this._mesh.count = capacity;

    for (let i = 0; i < capacity; i++) {
      _matrix.compose(_position, _identityQuat, _zeroScale);
      this._mesh.setMatrixAt(i, _matrix);
      this._mesh.setColorAt(i, _tmpColor.set(0xffffff));
    }
    this._mesh.instanceMatrix.needsUpdate = true;
    if (this._mesh.instanceColor) this._mesh.instanceColor.needsUpdate = true;

    scene.add(this._mesh);

    this._velX = new Float32Array(capacity);
    this._velY = new Float32Array(capacity);
    this._velZ = new Float32Array(capacity);
    this._posX = new Float32Array(capacity);
    this._posY = new Float32Array(capacity);
    this._posZ = new Float32Array(capacity);
    this._life = new Float32Array(capacity);
    this._maxLife = new Float32Array(capacity);
    this._baseScale = new Float32Array(capacity);
    this._drag = new Float32Array(capacity);
    this._gravity = new Float32Array(capacity);
    this._active = new Uint8Array(capacity);

    this._freeList = [];
    for (let i = capacity - 1; i >= 0; i--) this._freeList.push(i);
    this._activeQueue = [];
  }

  spawn({ x, y, z, vx = 0, vy = 0, vz = 0, life = 0.5, size = 0.15, color = 0xffffff, drag = 0.9, gravity = 0 }) {
    let index;
    if (this._freeList.length > 0) {
      index = this._freeList.pop();
    } else if (this._activeQueue.length > 0) {
      index = this._activeQueue.shift();
    } else {
      return;
    }

    this._active[index] = 1;
    this._posX[index] = x;
    this._posY[index] = y;
    this._posZ[index] = z;
    this._velX[index] = vx;
    this._velY[index] = vy;
    this._velZ[index] = vz;
    this._life[index] = life;
    this._maxLife[index] = life;
    this._baseScale[index] = size;
    this._drag[index] = drag;
    this._gravity[index] = gravity;
    this._activeQueue.push(index);

    this._mesh.setColorAt(index, _tmpColor.set(color));
    if (this._mesh.instanceColor) this._mesh.instanceColor.needsUpdate = true;
  }

  /** Radial burst helper — the common case for explosions/sparks. */
  burst({
    x, y, z,
    count = 12,
    speed = 4,
    speedVariance = 2,
    life = 0.5,
    lifeVariance = 0.2,
    size = 0.15,
    color = 0xffffff,
    gravity = 0,
    spread = Math.PI * 2,
    upBias = 0.3
  }) {
    for (let i = 0; i < count; i++) {
      const angle = Math.random() * spread;
      const s = Math.max(0.1, speed + (Math.random() * 2 - 1) * speedVariance);
      const vx = Math.cos(angle) * s;
      const vz = Math.sin(angle) * s;
      const vy = Math.random() * s * upBias;
      const l = Math.max(0.05, life + (Math.random() * 2 - 1) * lifeVariance);
      this.spawn({ x, y, z, vx, vy, vz, life: l, size, color, gravity });
    }
  }

  update(dt) {
    if (dt <= 0) return;
    let writeIndex = 0;
    const dragFrames = dt * 60;

    for (let k = 0; k < this._activeQueue.length; k++) {
      const index = this._activeQueue[k];
      this._life[index] -= dt;

      if (this._life[index] <= 0) {
        this._active[index] = 0;
        this._freeList.push(index);
        _matrix.compose(_position.set(0, 0, 0), _identityQuat, _zeroScale);
        this._mesh.setMatrixAt(index, _matrix);
        continue;
      }

      const dragFactor = Math.pow(this._drag[index], dragFrames);
      this._velX[index] *= dragFactor;
      this._velZ[index] *= dragFactor;
      this._velY[index] += this._gravity[index] * dt;

      this._posX[index] += this._velX[index] * dt;
      this._posY[index] += this._velY[index] * dt;
      this._posZ[index] += this._velZ[index] * dt;

      const t = 1 - this._life[index] / this._maxLife[index];
      const scale = Math.max(this._baseScale[index] * (1 - t), 0.0001);

      _position.set(this._posX[index], this._posY[index], this._posZ[index]);
      _scaleVec.set(scale, scale, scale);
      _matrix.compose(_position, _identityQuat, _scaleVec);
      this._mesh.setMatrixAt(index, _matrix);

      this._activeQueue[writeIndex++] = index;
    }
    this._activeQueue.length = writeIndex;
    this._mesh.instanceMatrix.needsUpdate = true;
  }

  get activeCount() {
    return this._activeQueue.length;
  }

  get capacity() {
    return this._capacity;
  }

  get mesh() {
    return this._mesh;
  }

  dispose(scene) {
    scene.remove(this._mesh);
    this._mesh.dispose();
    this._geometry.dispose();
    this._material.dispose();
  }
}

import * as THREE from 'three';
import { ObjectPool } from '../core/ObjectPool.js';

const RING_SEGMENTS = 48;

/**
 * Pooled expanding emissive rings for impacts/deaths. All rings share one
 * thin-ring geometry and animate purely via mesh scale + material opacity,
 * so growth never touches vertex data.
 */
export class ShockwaveRing {
  constructor(scene, { poolSize = 16, disposer = null } = {}) {
    this._scene = scene;
    this._disposer = disposer;

    this._sharedGeometry = new THREE.RingGeometry(0.85, 1, RING_SEGMENTS);
    this._sharedGeometry.rotateX(-Math.PI / 2);
    disposer?.trackGeometry(this._sharedGeometry);

    this._allInstances = [];
    this._activeRings = [];

    this._pool = new ObjectPool(
      () => this._createInstance(),
      (instance) => this._resetInstance(instance),
      poolSize
    );
  }

  _createInstance() {
    const material = new THREE.MeshStandardMaterial({
      color: 0x000000,
      emissive: 0xffffff,
      emissiveIntensity: 2.2,
      transparent: true,
      opacity: 0,
      depthWrite: false,
      side: THREE.DoubleSide,
      roughness: 1,
      metalness: 0
    });
    this._disposer?.trackMaterial(material);

    const mesh = new THREE.Mesh(this._sharedGeometry, material);
    mesh.visible = false;
    mesh.frustumCulled = false;
    this._scene.add(mesh);

    const instance = { mesh, material, life: 0, duration: 1, maxRadius: 3, minRadius: 0.2 };
    this._allInstances.push(instance);
    return instance;
  }

  _resetInstance(instance) {
    instance.mesh.visible = false;
    instance.material.opacity = 0;
    instance.life = 0;
  }

  spawn({ x, y = 0.05, z, color = 0xffffff, maxRadius = 3, minRadius = 0.2, duration = 0.6 }) {
    const instance = this._pool.acquire();
    instance.mesh.visible = true;
    instance.mesh.position.set(x, y, z);
    instance.material.emissive.set(color);
    instance.material.opacity = 1;
    instance.life = 0;
    instance.duration = duration;
    instance.maxRadius = maxRadius;
    instance.minRadius = minRadius;
    instance.mesh.scale.setScalar(minRadius);
    this._activeRings.push(instance);
  }

  update(dt) {
    for (let i = this._activeRings.length - 1; i >= 0; i--) {
      const instance = this._activeRings[i];
      instance.life += dt;
      const t = Math.min(instance.life / instance.duration, 1);
      const eased = 1 - Math.pow(1 - t, 3);
      const radius = instance.minRadius + (instance.maxRadius - instance.minRadius) * eased;
      instance.mesh.scale.setScalar(radius);
      instance.material.opacity = 1 - t;

      if (t >= 1) {
        this._activeRings.splice(i, 1);
        this._pool.release(instance);
      }
    }
  }

  dispose() {
    for (const instance of this._allInstances) {
      this._scene.remove(instance.mesh);
    }
    this._allInstances.length = 0;
    this._activeRings.length = 0;
  }
}

import * as THREE from 'three';
import { ObjectPool } from '../../shared/core/ObjectPool.js';

export const PROJECTILE_OWNER = {
  PLAYER: 'player',
  ENEMY: 'enemy',
  BOSS: 'boss'
};

/**
 * Pooled bullet system shared by player, enemies, and the UFO boss. One
 * InstancedMesh-free approach here (bullets are few, ~20 max) — a small pool
 * of individual meshes is simpler and still trivially cheap.
 */
export class ProjectileSystem {
  constructor(scene, { disposer = null, poolSize = 48, onDespawn = null } = {}) {
    this._scene = scene;
    this._disposer = disposer;
    this._onDespawn = onDespawn;

    this._sharedGeometry = new THREE.CapsuleGeometry(0.1, 0.3, 2, 6);
    disposer?.trackGeometry(this._sharedGeometry);

    this._allInstances = [];
    this._active = [];

    this._pool = new ObjectPool(
      () => this._createInstance(),
      (instance) => this._resetInstance(instance),
      poolSize
    );
  }

  _createInstance() {
    const material = new THREE.MeshStandardMaterial({
      color: 0x000000,
      emissive: 0xffffff,
      emissiveIntensity: 2,
      roughness: 0.3,
      metalness: 0.1
    });
    this._disposer?.trackMaterial(material);

    const mesh = new THREE.Mesh(this._sharedGeometry, material);
    mesh.visible = false;
    mesh.frustumCulled = false;
    this._scene.add(mesh);

    const instance = {
      mesh,
      material,
      owner: PROJECTILE_OWNER.PLAYER,
      vx: 0,
      vy: 0,
      vz: 0,
      radius: 0.12,
      damage: 1,
      alive: false,
      color: 0xffffff
    };
    this._allInstances.push(instance);
    return instance;
  }

  _resetInstance(instance) {
    instance.mesh.visible = false;
    instance.alive = false;
  }

  spawn({ x, y, z, vx, vy, vz, owner, radius = 0.12, damage = 1, color = 0xffffff, rotationX = 0 }) {
    const instance = this._pool.acquire();
    instance.mesh.position.set(x, y, z);
    instance.mesh.rotation.x = rotationX;
    instance.mesh.scale.setScalar(radius / 0.1);
    instance.mesh.visible = true;
    instance.material.emissive.set(color);
    instance.owner = owner;
    instance.vx = vx;
    instance.vy = vy;
    instance.vz = vz;
    instance.radius = radius;
    instance.damage = damage;
    instance.alive = true;
    this._active.push(instance);
    return instance;
  }

  kill(instance) {
    const idx = this._active.indexOf(instance);
    if (idx === -1) return;
    this._active.splice(idx, 1);
    this._pool.release(instance);
    this._onDespawn?.(instance);
  }

  update(dt, bounds) {
    for (let i = this._active.length - 1; i >= 0; i--) {
      const instance = this._active[i];
      instance.mesh.position.x += instance.vx * dt;
      instance.mesh.position.y += instance.vy * dt;
      instance.mesh.position.z += instance.vz * dt;

      if (
        instance.mesh.position.z < bounds.minZ ||
        instance.mesh.position.z > bounds.maxZ
      ) {
        this._active.splice(i, 1);
        this._pool.release(instance);
        this._onDespawn?.(instance);
      }
    }
  }

  get activeProjectiles() {
    return this._active;
  }

  forEachOwner(owner, callback) {
    for (const instance of this._active) {
      if (instance.owner === owner) callback(instance);
    }
  }

  dispose() {
    for (const instance of this._allInstances) {
      this._scene.remove(instance.mesh);
    }
    this._allInstances.length = 0;
    this._active.length = 0;
  }
}

